import{_ as e,o as i,c as r,a2 as l}from"./chunks/framework.Kw_SGbqu.js";const u=JSON.parse('{"title":"安装与升级","description":"","frontmatter":{},"headers":[],"relativePath":"guide/install.md","filePath":"guide/install.md"}'),o={name:"guide/install.md"};function t(n,a,d,s,h,c){return i(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="安装与升级" tabindex="-1">安装与升级 <a class="header-anchor" href="#安装与升级" aria-label="Permalink to &quot;安装与升级&quot;">​</a></h1><p>FurinaChronicle 优先支持 Windows 和 Android。请以项目正式发布公告中提供的下载地址、平台要求和包说明为准。开发构建与验收构建可能使用不同的数据目录或应用标识。</p><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><ol><li>下载发布公告中标为 Windows x64 的压缩包。</li><li>解压到一个独立目录，打开 <code>FurinaChronicle.Windows.exe</code>。</li><li>已使用过旧版时，按应用内提示校验和备份现有数据，再确认接管。需要联网刷新时，按提示重新授权游戏通行证。</li></ol><p>升级时先退出应用，再解压到新的版本目录。涉及数据库升级时，保留升级前备份，并以该发行版的回退说明为准。</p><h2 id="android" tabindex="-1">Android <a class="header-anchor" href="#android" aria-label="Permalink to &quot;Android&quot;">​</a></h2><p>从项目公告下载与你的设备和发行渠道匹配的 APK。Android 可能要求授权当前浏览器或文件管理器安装应用。</p><p>升级前先导出档案备份。若系统拒绝覆盖安装，核对新旧包使用的应用标识、签名和版本。保留旧应用，直到确认已有可读取的备份。</p><h2 id="开始使用" tabindex="-1">开始使用 <a class="header-anchor" href="#开始使用" aria-label="Permalink to &quot;开始使用&quot;">​</a></h2><p>打开档案与账号管理，创建或选择用于保存记录的档案。导入本地文件可以独立进行；使用游戏账号在线刷新时，在用户页选择通行证和对应的角色。</p><ul><li><a href="./gacha.html">抽卡记录</a></li><li><a href="./archive.html">备份与迁移</a></li><li><a href="https://github.com/DaKang233/FurinaChronicle" target="_blank" rel="noreferrer">项目源码与问题反馈</a></li></ul>',11)])])}const _=e(o,[["render",t]]);export{u as __pageData,_ as default};
